    "Manual analog gravity displacement workhorses with dual safety thermostats.": "เครื่องแทนที่แรงโน้มถ่วงแบบอนาล็อกแมนนวลที่ทนทาน มีเทอร์โมสแตทความปลอดภัยคู่",
