    "1.8L cassette, 6 min unwrapped cycle, fresh distilled water dose every single run.": "ตลับขนาด 1.8 ลิตร รอบ 6 นาทีไม่ห่อ ใช้น้ำกลั่นใหม่ในทุกรอบ",
    "5.1L cassette accommodating full forceps trays with direct USB and network audit logging.": "ตลับขนาด 5.1 ลิตร รองรับถาดคีมเต็มชุด พร้อม USB โดยตรงและการบันทึกการตรวจสอบผ่านเครือข่าย",
    "Swiss compact cassette-profile Class B autoclave (7 min unwrapped, 15 min wrapped).": "เครื่องนึ่งฆ่าเชื้อ Class B ของสวิสขนาดกะทัดรัดรูปแบบตลับ (7 นาทีไม่ห่อ, 15 นาทีห่อ)",
