    "Uses a specialized chemical solution (alcohol, formaldehyde, ketones, and <15% water) vaporized under pressure. Because moisture is minimal, instruments emerge completely dry and rust-free without dulling sharp cutting edges.": "ใช้สารละลายเคมีเฉพาะ (แอลกอฮอล์ ฟอร์มาลดีไฮด์ คีโตน และน้ำ <15%) ที่ระเหยภายใต้แรงดัน เนื่องจากความชื้นมีน้อยมาก เครื่องมือจึงออกมาแห้งสนิทและไม่เกิดสนิม โดยไม่ทำให้ใบมีดคมทื่อ",
