    "Clinical Aseptic Guidance:": "คำแนะนำด้านการปลอดเชื้อทางคลินิก:",
    "Vascular tissue with high lymphatic drainage. Minimal puncture resistance and rapid primary epithelization. Maintain perpendicular angle to lobule plane.": "เนื้อเยื่อหลอดเลือดที่มีการระบายน้ำเหลืองสูง ต้านทานการเจาะน้อยและเกิดเยื่อบุผิวปฐมภูมิเร็ว รักษามุมตั้งฉากกับระนาบของติ่งหู",
    "Autoclaves kill microorganisms using pressurized steam at high temperatures.\n                            The combination of heat, pressure, and time destroys all bacteria, viruses,\n                            fungi, and spores, including hard-to-kill organisms like": "ออโตเคลฟทำลายจุลชีพด้วยไอน้ำอัดความดันที่อุณหภูมิสูง การรวมกันของความร้อน ความดัน และเวลาทำลายแบคทีเรีย ไวรัส เชื้อรา และสปอร์ทั้งหมด รวมถึงสิ่งมีชีวิตที่ทำลายยาก เช่น",
    "Found something useful? Got ideas for improvements? We're all ears!\n                        Help us make this tool even better for everyone in our body art family.": "พบสิ่งที่มีประโยชน์? มีไอเดียสำหรับการปรับปรุงไหม? เรายินดีรับฟัง! ช่วยเราทำให้เครื่องมือนี้ดียิ่งขึ้นสำหรับทุกคนในครอบครัวบอดี้อาร์ตของเรา",
