    "After corrective action or service, the unit must pass three consecutive empty/full chamber biological indicator tests before being returned to patient service.": "หลังการแก้ไขหรือการบริการ เครื่องต้องผ่านการทดสอบตัวบ่งชี้ทางชีวภาพแบบห้องว่าง/เต็มติดต่อกันสามครั้งก่อนนำกลับมาใช้งานกับผู้ป่วย",
