    "Health departments and biomedical standards mandate annual professional autoclave chamber calibration (every 365 days). Configure your certification details below to trigger automated compliance warnings.": "หน่วยงานสาธารณสุขและมาตรฐานชีวการแพทย์กำหนดให้มีการสอบเทียบห้องออโตเคลฟโดยผู้เชี่ยวชาญประจำปี (ทุก 365 วัน) กำหนดรายละเอียดใบรับรองของคุณด้านล่างเพื่อเรียกการแจ้งเตือนการปฏิบัติตามข้อกำหนดอัตโนมัติ",
    "Health departments and biomedical standards mandate maintaining sterilization logs and biological spore testing records for a minimum of 3 years (36 months). Clean up outdated records or download structured safety JSON backups to secure your studio compliance.": "หน่วยงานสาธารณสุขและมาตรฐานชีวการแพทย์กำหนดให้เก็บบันทึกการฆ่าเชื้อและบันทึกการทดสอบสปอร์ทางชีวภาพไว้อย่างน้อย 3 ปี (36 เดือน) ล้างบันทึกที่ล้าสมัยหรือดาวน์โหลดการสำรองข้อมูลความปลอดภัย JSON เพื่อรักษาการปฏิบัติตามข้อกำหนดของสตูดิโอ",
    "Heat-Sealed Nylon Foil Tubing (Dry Heat / Steam Compatible)": "ท่อฟอยล์ไนลอนปิดผนึกด้วยความร้อน (ใช้ได้กับความร้อนแห้ง / ไอน้ำ)",
    "Heat-Sealed Poly/Paper Roll Pouch (Heavy Duty 3-Layer)": "ซองม้วนโพลี/กระดาษปิดผนึกด้วยความร้อน (ทนทานสูง 3 ชั้น)",
    "Heat-up + Exposure + Dry": "ให้ความร้อน + สัมผัส + อบแห้ง",
    "Heated Dry Phase": "เฟสอบแห้งด้วยความร้อน",
    "Heating & Warm-up Lag": "ความล่าช้าของการให้ความร้อนและการอุ่นเครื่อง",
    "Heating Element & Chamber Coils (Scale Buildup Risk)": "องค์ประกอบความร้อนและขดลวดห้อง (เสี่ยงต่อการสะสมตะกรัน)",
    "Heating Lag / Slow Cycle Time": "ความล่าช้าของการให้ความร้อน / เวลารอบช้า",
