    "Hero Banner (120px)": "แบนเนอร์ฮีโร่ (120px)",
    "Hey there, fellow body art enthusiast! Whether you're a professional tattooist, piercer, or someone who loves body art as much as we do – we're all in this together. Our passion doesn't get much support out there, so let's stick together and build the best tools to help our community thrive!": "สวัสดีเพื่อนผู้หลงใหลในศิลปะบนร่างกาย ไม่ว่าคุณจะเป็นช่างสักมืออาชีพ ช่างเจาะ หรือคนที่รักศิลปะบนร่างกายพอๆ กับเรา เราทุกคนอยู่ในเรื่องเดียวกัน ความหลงใหลของเราไม่ค่อยได้รับการสนับสนุนมากนัก มาช่วยกันสร้างเครื่องมือที่ดีที่สุดเพื่อให้ชุมชนของเราเติบโต!",
