    "High-Traffic Procedure Drawer (Frequent Handling)": "ลิ้นชักขั้นตอนที่มีการใช้งานหนาแน่น (มีการหยิบจับบ่อย)",
    "High-Urgency Alert": "การแจ้งเตือนระดับเร่งด่วน",
