    "Hold steady for half a second. Once recognized, the laser reticle turns solid green with a checkmark (✓) and instantly retrieves machine history.": "ค้างไว้ครู่หนึ่ง เมื่อจดจำได้ เส้นเล็งเลเซอร์จะเปลี่ยนเป็นสีเขียวทึบพร้อมเครื่องหมายถูก (✓) และดึงประวัติเครื่องทันที",
