    "ITEM:": "รายการ:",
    "Idaho": "ไอดาโฮ",
    "Identify whether the failure was caused by mechanical failure (door gasket leak, temperature sensor drift, heating element failure, air valve clogging), operator error (overloading, incorrect packaging, wet steam), or biological indicator handling.": "ระบุว่าความล้มเหลวเกิดจากความผิดพลาดทางกลไก (ปะเก็นประตูรั่ว เซ็นเซอร์อุณหภูมิคลาดเคลื่อน องค์ประกอบความร้อนล้มเหลว วาล์วอากาศอุดตัน) ความผิดพลาดของผู้ปฏิบัติงาน (บรรจุเกิน บรรจุภัณฑ์ไม่ถูกต้อง ไอน้ำเปียก) หรือการจัดการตัวบ่งชี้ทางชีวภาพ",
    "If bright studio ceiling lamps reflect off glossy sticker lamination, tilt your phone slightly (5°–10°) to remove washed-out glare.": "หากแสงจากโคมไฟเพดานของสตูดิโอสะท้อนบนแผ่นลามิเนตสติกเกอร์ที่มันวาว ให้เอียงโทรศัพท์เล็กน้อย (5°–10°) เพื่อกำจัดแสงสะท้อนที่ทำให้ภาพซีด",
    "Illinois": "อิลลินอยส์",
    "Immediate Re-Sterilization Required If:": "ต้องฆ่าเชื้อใหม่ทันทีหาก:",
    "Implant Jewelry": "เครื่องประดับฝังในร่างกาย",
    "Implant Jewelry Pouches": "ซองเครื่องประดับฝังในร่างกาย",
    "Implant-grade titanium/gold barbells, flatbacks, CBRs (25g each)": "บาร์เบลล์ ฟลัตแบ็ก และ CBR ไทเทเนียม/ทองระดับฝังในร่างกาย (ชิ้นละ 25g)",
    "Import JSON": "นำเข้า JSON",
    "Import presets & spore test history from a backup JSON": "นำเข้าพรีเซ็ตและประวัติการทดสอบสปอร์จากไฟล์สำรอง JSON",
    "Improper sterilization can result in serious infections and legal liability. When in doubt, consult with a sterilization specialist, your autoclave manufacturer, or your local health department.": "การฆ่าเชื้อที่ไม่เหมาะสมอาจก่อให้เกิดการติดเชื้อร้ายแรงและความรับผิดทางกฎหมาย เมื่อมีข้อสงสัย ให้ปรึกษาผู้เชี่ยวชาญด้านการฆ่าเชื้อ ผู้ผลิตออโตเคลฟของคุณ หรือกรมสาธารณสุขในท้องถิ่นของคุณ",
    "In-studio 24h/48h incubation tracker & interactive Class 5 integrator and": "ตัวติดตามการบ่ม 24 ชม./48 ชม. ในสตูดิโอและตัวรวม Class 5 แบบโต้ตอบ และ",
    "Inches": "นิ้ว",
    "Includes biological indicator test dates, pass/fail lethality outcomes, incubation hours & temps, control vial verification, technician notes, and days interval.": "รวมวันที่ทดสอบตัวบ่งชี้ทางชีวภาพ ผลความสามารถในการฆ่าผ่าน/ไม่ผ่าน ชั่วโมงและอุณหภูมิการบ่ม การตรวจสอบหลอดควบคุม หมายเหตุของช่างเทคนิค และช่วงเวลาเป็นวัน",
