    "Infection control standards require conducting an opening equipment inspection and recording your first autoclave cycle parameters or daily maintenance check before packaging client instruments.": "มาตรฐานการควบคุมการติดเชื้อกำหนดให้ทำการตรวจสอบอุปกรณ์เปิดเครื่องและบันทึกพารามิเตอร์รอบออโตเคลฟแรกหรือการตรวจสอบการบำรุงรักษารายวัน ก่อนบรรจุเครื่องมือของลูกค้า",
