    "Inter-Pack Steam Clearance:": "ระยะห่างไอน้ำระหว่างชุด:",
    "Interactive clinical diagnosis wizard with multi-step root-cause analysis, error code lookup (Midmark, Tuttnauer, Statim, Scican), and mandatory corrective actions.": "ตัวช่วยวินิจฉัยทางคลินิกแบบโต้ตอบ พร้อมการวิเคราะห์สาเหตุหลักหลายขั้นตอน การค้นหารหัสข้อผิดพลาด (Midmark, Tuttnauer, Statim, Scican) และการดำเนินการแก้ไขที่จำเป็น",
