    "The official monthly compliance audit report (including full batch logs, biological spore pass rates, and calibration verification) will be sent here automatically on the 1st of each calendar month.": "รายงานการตรวจสอบการปฏิบัติตามข้อกำหนดรายเดือนอย่างเป็นทางการ (รวมบันทึกชุดทั้งหมด อัตราการผ่านการทดสอบสปอร์ทางชีวภาพ และการยืนยันการสอบเทียบ) จะถูกส่งมาที่นี่โดยอัตโนมัติในวันที่ 1 ของทุกเดือนตามปฏิทิน",
    "The steam-sensitive chemical pellet melted and wicked safely past the red reject zone into the dark blue accept window, confirming all 3 critical sterilization parameters were achieved inside the pack.": "เม็ดสารเคมีที่ไวต่อไอน้ำละลายและเคลื่อนผ่านโซนปฏิเสธสีแดงไปยังช่องยอมรับสีน้ำเงินเข้มอย่างปลอดภัย ยืนยันว่าบรรลุพารามิเตอร์การฆ่าเชื้อที่สำคัญทั้ง 3 ประการภายในแพ็ก",
