    "Track cumulative autoclave running hours, door gasket odometer, chamber descaling intervals, and annual calibration certifications without external API costs.": "ติดตามชั่วโมงการทำงานสะสมของออโตเคลฟ ระยะทางของปะเก็นประตู ช่วงการขจัดตะกรันห้อง และใบรับรองการสอบเทียบประจำปี โดยไม่มีค่าใช้จ่ายของ API ภายนอก",
    "Tracks total cycle duration (exposure plateau + drying + chamber heat-up) to monitor machine thermal efficiency and detect heating drift": "ติดตามระยะเวลารอบรวม (ช่วงการสัมผัสที่ระดับคงที่ + การอบแห้ง + การอุ่นห้อง) เพื่อตรวจสอบประสิทธิภาพทางความร้อนของเครื่องและตรวจจับการเคลื่อนของการให้ความร้อน",
