    "Weekly Digest": "สรุปรายสัปดาห์",
    "Weekly inspection of gaskets and chamber, monthly deep cleaning, annual professional calibration, and immediate repair of any issues are essential. Preventive maintenance prevents costly breakdowns and ensures consistent sterilization performance.": "การตรวจสอบปะเก็นและห้องประจำสัปดาห์ การทำความสะอาดอย่างละเอียดรายเดือน การสอบเทียบมืออาชีพประจำปี และการซ่อมแซมปัญหาใดๆ ทันทีเป็นสิ่งจำเป็น การบำรุงรักษาเชิงป้องกันช่วยป้องกันการเสียหายที่มีค่าใช้จ่ายสูงและรับประกันประสิทธิภาพการฆ่าเชื้อที่สม่ำเสมอ",
    "Weekly or monthly spore testing per national guidelines + daily Bowie-Dick": "การทดสอบสปอร์รายสัปดาห์หรือรายเดือนตามแนวทางระดับชาติ + การทดสอบ Bowie-Dick รายวัน",
    "Weekly spore test (Geobacillus stearothermophilus) + every implant load": "การทดสอบสปอร์รายสัปดาห์ (Geobacillus stearothermophilus) + ทุกโหลดของการฝังในร่างกาย",
    "Weekly spore test + electronic data logger batch release validation": "การทดสอบสปอร์รายสัปดาห์ + การตรวจสอบการปล่อยชุดด้วยเครื่องบันทึกข้อมูลอิเล็กทรอนิกส์",
    "West Virginia": "เวสต์เวอร์จิเนีย",
    "Wet Pack Detected (Moisture inside pouches upon unseal)": "ตรวจพบชุดเปียก (ความชื้นภายในซองเมื่อเปิดซีล)",
    "Wet Packs / Moisture on Pouches": "ชุดเปียก / ความชื้นบนซอง",
    "What do you love? What could be better? Any features you'd like to see? We genuinely want to hear from you!": "คุณชอบอะไร? อะไรที่ควรดีขึ้น? มีคุณสมบัติใดที่อยากเห็นบ้าง? เรารับฟังความคิดเห็นของคุณอย่างจริงใจ!",
    "When Spore Tests Fail": "เมื่อการทดสอบสปอร์ล้มเหลว",
    "While we strive to maintain accurate regulatory information, requirements can change. Always verify current requirements with your local health department.": "แม้เราจะพยายามรักษาข้อมูลกฎระเบียบให้ถูกต้อง แต่ข้อกำหนดอาจเปลี่ยนแปลงได้ ควรตรวจสอบข้อกำหนดปัจจุบันกับกรมสาธารณสุขท้องถิ่นของคุณเสมอ",
    "Why Spore Tests Matter": "เหตุใดการทดสอบสปอร์จึงสำคัญ",
    "Wipe silicone door gasket & mating chamber surface with non-abrasive cloth. Check tray rack for debris.": "เช็ดปะเก็นซิลิโคนประตูและพื้นผิวห้องที่สัมผัสด้วยผ้าที่ไม่ขัดถู ตรวจสอบชั้นวางถาดว่ามีเศษหรือไม่",
    "Wisconsin": "วิสคอนซิน",
    "Within state interval": "อยู่ในช่วงเวลาของรัฐ",
    "Wrapped / Heat-Sealed Pouch (sterile storage)": "ซองห่อ / ปิดผนึกด้วยความร้อน (การเก็บรักษาแบบปลอดเชื้อ)",
    "Wrapped Instruments (pouched)": "เครื่องมือที่ห่อ (บรรจุในซอง)",
    "Wrapped Solid Instruments (Pouches / Tubing)": "เครื่องมือทึบที่ห่อ (ซอง / ท่อ)",
    "Wrapped pouches require steam penetration & dry phase. Unwrapped flash cycles are strictly for immediate emergency use. Hollow instruments (lumens/piercing cannulas) mandate dynamic vacuum air removal.": "ซองที่ห่อต้องให้ไอน้ำซึมผ่านและมีเฟสการอบแห้ง รอบแฟลชที่ไม่ห่อใช้ได้เฉพาะกรณีฉุกเฉินทันทีเท่านั้น เครื่องมือกลวง (ช่องกลวง / ท่อเจาะ) ต้องดึงอากาศออกด้วยสุญญากาศแบบไดนามิก",
