    "txt.speed.up.clinical.documentatio": "เร่งการจัดทำเอกสารทางคลินิกและขั้นตอนการทำงานด้วยปุ่มลัด",
    "txt.stop.using.the.autoclave.immed": "หยุดใช้ออโตเคลฟทันทีหากการทดสอบสปอร์ล้มเหลว เรียกคืนเครื่องมือทั้งหมดที่ประมวลผลตั้งแต่การทดสอบที่สำเร็จครั้งล่าสุด ห้ามใช้เครื่องมือจนกว่าจะระบุปัญหา แก้ไข และการทดสอบสปอร์ใหม่ผ่าน ติดต่อลูกค้าหากจำเป็น",
    "txt.studio.efficiency.tip.streamli": "เคล็ดลับประสิทธิภาพของสตูดิโอ: การทำให้งานธุรการของคุณคล่องตัวช่วยให้คุณมุ่งความสนใจไปที่งานศิลปะได้มากขึ้น เครื่องมือของเราออกแบบด้วยแนวคิดที่ให้สตูดิโอเป็นสำคัญ เพื่อให้มีประสิทธิภาพสูง ความเป็นส่วนตัวของข้อมูล และความแม่นยำระดับมืออาชีพ",
    "txt.survivability.of.bacterial.spo": "การอยู่รอดของสปอร์แบคทีเรียบ่งชี้ว่าพารามิเตอร์การฆ่าเชื้อล้มเหลวระหว่างการประมวลผล",
    "txt.thanks.we.ll.notify.you.when.n": "✅ ขอบคุณ! เราจะแจ้งเมื่อมีเครื่องมือใหม่เปิดตัว!",
    "txt.the.steam.sensitive.chemical.p": "เม็ดสารเคมีที่ไวต่อไอน้ำละลายและเคลื่อนผ่านโซนปฏิเสธสีแดงไปยังช่องยอมรับสีน้ำเงินเข้มอย่างปลอดภัย ยืนยันว่าบรรลุพารามิเตอร์การฆ่าเชื้อที่สำคัญทั้ง 3 ประการภายในแพ็ก",
    "txt.track.biological.indicator.let": "ติดตามการทดสอบการทำลายตัวบ่งชี้ทางชีวภาพ ตรวจสอบช่องว่างเวลาการปฏิบัติตามข้อกำหนด และยืนยันการสอบเทียบอุปกรณ์ประจำปี",
    "txt.track.cumulative.autoclave.run": "ติดตามชั่วโมงการทำงานสะสมของออโตเคลฟ ระยะทางของปะเก็นประตู ช่วงการขจัดตะกรันห้อง และใบรับรองการสอบเทียบประจำปี โดยไม่มีค่าใช้จ่าย API ภายนอก",
    "txt.tracks.total.cycle.duration.ex": "ติดตามระยะเวลารอบรวม (ช่วงการสัมผัสที่ระดับคงที่ + การอบแห้ง + การอุ่นห้อง) เพื่อตรวจสอบประสิทธิภาพทางความร้อนของเครื่องและตรวจจับการเคลื่อนของการให้ความร้อน",
    "txt.triple.rapid.pulse.beep.modele": "เสียงบี๊บชีพจรเร็วสามครั้งที่จำลองจากออโตเคลฟทางการแพทย์",
    "txt.upload.your.studio.logo.and.pr": "อัปโหลดโลโก้และโปรไฟล์สตูดิโอของคุณเพื่อสร้างตราสินค้าให้บันทึกการตรวจสอบรอบและการส่งออก PDF การปฏิบัติตามข้อกำหนดทั้งหมดที่พิมพ์ได้",
    "txt.verification.required.for.toda": "ต้องมีการยืนยันสำหรับวันนี้ก่อนขั้นตอนทางคลินิก",
    "txt.visualizing.time.gap.days.betw": "แสดงช่องว่างเวลา (จำนวนวันระหว่างการทดสอบ) เทียบกับเกณฑ์การปฏิบัติตามข้อกำหนดของรัฐ",
    "txt.warm.harmonic.triad.chime.with": "เสียงกริ่งสามเสียงฮาร์มอนิกอุ่นพร้อมเสียงก้องที่นุ่มนวล",
    "txt.weekly.inspection.of.gaskets.a": "การตรวจสอบปะเก็นและห้องประจำสัปดาห์ การทำความสะอาดอย่างละเอียดรายเดือน การสอบเทียบมืออาชีพประจำปี และการซ่อมแซมปัญหาใดๆ ทันทีเป็นสิ่งจำเป็น การบำรุงรักษาเชิงป้องกันช่วยป้องกันการเสียหายที่มีค่าใช้จ่ายสูงและรับประกันประสิทธิภาพการฆ่าเชื้อที่สม่ำเสมอ",
    "txt.wipe.silicone.door.gasket.mati": "เช็ดปะเก็นซิลิโคนประตูและพื้นผิวห้องที่สัมผัสด้วยผ้าที่ไม่ขัดถู ตรวจสอบชั้นวางถาดว่ามีเศษหรือไม่",
